    /** حوارات تركية واقعية (49 حواراً). */
    val scenarios: List<DailyScenarioEntity> = listOf(
        DailyScenarioEntity(7000, "Tanışma 1", "تعارف في الشارع (A1) — محايد", "Merhaba, ben Ali.\nMerhaba Ali, ben Mehmet. Memnun oldum.\nBen de memnun oldum. Nerelisin?\nYemenliyim. Sen?\nBen İstanbulluyum.", "تركي:\nترجمة: مرحبًا أنا علي. — مرحبًا علي أنا محمد، تشرفت. — وأنا كذلك. من أين أنت؟ — يمني. وأنت؟ — من إسطنبول.\nحرفي: Nerelisin = من أي بلد/مدينة أنت (لاحقة -lI + شخص).\nكلمات: memnun olmak، nereli، -lI.\nقاعدة: الخبر يأخذ لاحقة الشخص: Yemenli-y-im.\nأسلوب: محايد. مع أكبر سنًا: Nerelisiniz?\nبدائل: Adın ne? / İsminiz nedir? / Tanıştığımıza memnun oldum.", 0, "تعارف", "TR"),
        DailyScenarioEntity(7001, "Tanışma 2", "صديقان بعد غياب (A2) — يومي", "Oooo, neredeydin?\nİş yoğundu ya.\nÖzledik seni. Çay içelim mi?\nHadi, ben ısmarlarım.", "ترجمة: وينك؟ — الشغل كان زحمة والله. — اشتقنا لك. نشرب شاي؟ — يلا، عليّ الحساب.\nأسلوب: يومي ودود. ya تلطّف. Ismarlamak = يعزم (ليس «يطلب» فقط).\nتحذير: Neredeydin? لغريب = تدخل.", 0, "تعارف", "TR"),
        DailyScenarioEntity(7002, "Pazar 3", "محل ملابس — زبون مهذب (A2)", "Kolay gelsin. Şu gömleği bakabilir miyim?\nTabii, buyurun. Bedeniniz nedir?\nMedium. Mavisi var mı?\nBir bakayım… Evet, buyurun.\nDeneme kabini nerede?\nSolda.", "بدائل بائع: Ne bakmıştınız? Size bakayım mı?", 0, "سوق", "TR"),
        DailyScenarioEntity(7003, "Pazar 4", "مساومة بازار (B1) — يومي سوقي", "Abi, bu lamba ne kadar?\nİki bin.\nBiraz yüksek. Son fiyat nedir?\nNakit olursa bin sekiz.\nBin beş veririm.\nOlmaz. Bin yedi, son.\nTamam, tamam. Paketler misin?", "ترجمة طبيعية: يا أخ، هاللمبة بكم؟ — ألفين. — غالية شوي. آخر سعر؟ — نقدًا ألف وثمانمئة. — بألف وخمسمئة. — لا. ألف وسبعمئة آخر كلام. — ماشي. تغلفها؟\nثقافة: ابتسم. لا تُهين السلعة (Bu ne ya, kötü) إلا إن كنت تعرف البائع.\nسجل: Abi دافئ في السوق. في مول فخم: Hocam / Beyefendi أو بلا نداء.", 0, "سوق", "TR"),
        DailyScenarioEntity(7004, "Pazar 5", "بائع يجذب زبونًا (B1)", "Gel gel, bak bak. Zarar yok.\nYok, sadece bakıyorum.\nBakmakla olmaz, bir dene. Sana yakışır.\nPahalı gibi.\nSen söyle, bir fiyat yapalım.", "أسلوب: سوقي. لا تستخدم Gel gel في بووتيك هادئ.", 0, "سوق", "TR"),
        DailyScenarioEntity(7005, "Restoran 6", "مطعم (A1–A2)", "Buyurun, kaç kişisiniz?\nİki.\nŞuraya buyurun. Menü.\nBir mercimek çorbası, bir Adana. Acısız.\nİçmek için?\nİki ayran.\n… Afiyet olsun.\nTeşekkürler. Hesap lütfen.\nKart geçiyor.\nTamam.", "كلمات: acısız = بلا حرارة. acılı = حار. az acılı = حار خفيف.\nرد على Afiyet olsun: Teşekkürler (ليس Afiyet olsun إلا إن كنت ترد بالمثل أحيانًا).", 0, "مطعم", "TR"),
        DailyScenarioEntity(7006, "Restoran 7", "مقهى وطلب تفاصيل (A2)", "Bir Türk kahvesi.\nSade mi, orta mı, şekerli mi?\nOrta.\nBaşka?\nBir bardak su, lütfen.", "نطق: sade ≈ ساده، orta ≈ أورتا.", 0, "مطعم", "TR"),
        DailyScenarioEntity(7007, "Ulaşım 8", "دلموش / باص (A1) — ضروري جدًا", "Bu dolmuş Üsküdar’a gidiyor mu?\nGidiyor, bin.\n… İnecek var!\nDurak mı?\nEvet, köşede.", "حرفي: İnecek var = يوجد من سينزل.\nبدائل: Müsait bir yerde inebilir miyim?", 0, "مواصلات", "TR"),
        DailyScenarioEntity(7008, "Seyahat 9", "ضياع في الشارع (A1)", "Affedersiniz, metro nerede acaba?\nDümdüz, sonra sağda. Beş dakika.\nÇok teşekkür ederim.\nRica ederim, kolay gelsin.", "acaba يلطّف السؤال. أسلوب: مهذب محايد.", 0, "سفر", "TR"),
        DailyScenarioEntity(7009, "Ulaşım 10", "تاكسي (A2)", "Müsait misiniz?\nEvet, buyurun. Nereye?\nKadıköy iskele, lütfen. Taksimetre açık olsun.\nTamam.\nŞurada ineyim. Ne kadar?\nYüz yetmiş.\nKart olur mu?\nOlur.", "مهم: Taksimetre açık olsun طلب مشروع.", 0, "مواصلات", "TR"),
        DailyScenarioEntity(7010, "Seyahat 11", "فندق استقبال (A2)", "İyi akşamlar. Rezervasyonum var. Adım Ali Ahmed.\nBir dakika… Evet, iki gece, tek yatak. Pasaport?\nBuyurun. Kahvaltı dahil mi?\nEvet, yediden ona.\nWi-Fi şifresi?\nKartın arkasında.", "حوار للاستماع والقراءة. راجع المكتبة المرجعية للشرح الكامل.", 0, "سفر", "TR"),
        DailyScenarioEntity(7011, "Seyahat 12", "مطار — تأخير (B1)", "Uçuş neden gecikti?\nTeknik bir aksaklık var. Yaklaşık bir saat.\nAktarmayı kaçıracak mıyım?\nBakalım, yardımcı olmaya çalışacağız.", "أسلوب: رسمي–محايد. أنت: Siz دائمًا.", 0, "سفر", "TR"),
        DailyScenarioEntity(7012, "Sağlık 13", "صيدلية (A1–A2)", "Kolay gelsin. Başım çok ağrıyor. Ağrı kesici var mı?\nMideniz hassas mı?\nBiraz.\nBunu yemekten sonra alın.\nTeşekkürler.", "حوار للاستماع والقراءة. راجع المكتبة المرجعية للشرح الكامل.", 0, "صحة", "TR"),
        DailyScenarioEntity(7013, "Sağlık 14", "مستشفى استقبال (A2–B1)", "Merhaba, muayene olmak istiyorum.\nSigortanız var mı?\nTuristim, yok.\nO zaman ücretli. Şikayetiniz nedir?\nDün akşamdan beri ateşim var.", "كلمات: şikayet هنا = الشكوى الطبية لا الاعتراض.", 0, "صحة", "TR"),
        DailyScenarioEntity(7014, "Tanışma 15", "جيران — ضوضاء (B1) — مهذب", "İyi akşamlar, kusura bakmayın rahatsız ettim.\nBuyurun?\nMüzik biraz yüksek, çocuklar uyuyamıyor.\nAa özür dilerim, hemen kısacağım.\nÇok teşekkürler, iyi akşamlar.", "لا تقل: Kes şu sesi إلا في شجار. ذلك عامي عدواني.", 0, "تعارف", "TR"),
        DailyScenarioEntity(7015, "Günlük 16", "اعتذار عن التأخير (A2)", "Geç kaldım, çok özür dilerim. Yol yoğundu.\nTamam, sorun değil. Gel otur.", "بدائل أقوى: Kusura bakma. Affet.", 0, "عام", "TR"),
        DailyScenarioEntity(7016, "İletişim 17", "هاتف — شخص غير موجود (A2)", "Alo, Mehmet Bey orada mı?\nŞu an dışarıda. Mesaj bırakayım mı?\nLütfen arasın, Ali. Numaram kayıtlı.\nTamam, ileteceğim.", "حوار للاستماع والقراءة. راجع المكتبة المرجعية للشرح الكامل.", 0, "اتصال", "TR"),
        DailyScenarioEntity(7017, "İletişim 18", "واتساب (A2) — يومي رقمي", "slm nbr\niyidir senden\nakşam çay?\nolur saat kaç\n8\ntmm görüşürüz", "أسلوب: عامي مكتوب. لا ترسله لمديرك أول مرة.", 0, "اتصال", "TR"),
        DailyScenarioEntity(7018, "Pazar 19", "شكوى منتج (B1)", "Dün aldığım ayakkabı hatalı. Numara yanlış gelmiş.\nÖzür dileriz. Değişim yapabiliriz. Fişiniz var mı?\nVar, buyurun.\nTeşekkürler, hemen bakıyoruz.", "قاعدة: gelmiş = -miş للشائعة/النتيجة التي اكتشفتها الآن.", 0, "سوق", "TR"),
        DailyScenarioEntity(7019, "Pazar 20", "زبون غاضب — تهدئة (B2)", "İki saattir bekliyorum! Bu ne ya?\nHaklısınız, özür dileriz. Hemen ilgileniyorum. Bir çay söyleyeyim mi?\nÇayla olmaz, işim var.\nBeş dakikada çözüyoruz.", "مهارة: Haklısınız قبل الشرح. لا تبدأ بـ Ama.", 0, "سوق", "TR"),
        DailyScenarioEntity(7020, "Günlük 21", "لا تفهم الكلمة (A1) — ضروري", "Anlamadım. Ne demek?\n“Fiş” yani makbuz, kâğıt.\nAnladım, teşekkürler. Yavaş söyler misiniz?", "بدائل: Bir daha söyler misiniz? Türkçem henüz az.", 0, "عام", "TR"),
        DailyScenarioEntity(7021, "Tanışma 22", "صديقان يمزحان (B1)", "Yine geç kaldın.\nTrafik ya.\nTrafik mi, sen mi?\nTamam dur, takılma. Çay ısmarlıyorum.\nBu sefer kurtardın.", "takılmak هنا = يمازح/يدايق. Takılma = لا تأخذها جدًا / لا تضايق.\nمع غريب: لا.", 0, "تعارف", "TR"),
        DailyScenarioEntity(7022, "Günlük 23", "دعوة بيت (A2)", "Akşam bize uğrar mısın?\nUğrarım, kaçta?\nYedide. Çoluk çocuk da var.\nHarika, ne getireyim?\nHiçbir şey, yeter ki gel.", "ثقافة: المجيء بيد فارغة ثقيل أحيانًا؛ حلويات أو فاكهة مقبولة حتى لو قالوا لا تجلب شيئًا.", 0, "عام", "TR"),
        DailyScenarioEntity(7023, "Günlük 24", "عند الدخول للبيت", "Hoş geldin!\nHoş bulduk.\nBuyur, içeri geç. Ayakkabılarını çıkarabilirsin.\nTabii.", "حوار للاستماع والقراءة. راجع المكتبة المرجعية للشرح الكامل.", 0, "عام", "TR"),
        DailyScenarioEntity(7024, "Günlük 25", "بنك (B1)", "Hesap açmak istiyorum.\nKimliğiniz? Adres belgesi?\nPasaportum var, geçici adres.\nTamam, formu dolduralım.", "حوار للاستماع والقراءة. راجع المكتبة المرجعية للشرح الكامل.", 0, "عام", "TR"),
        DailyScenarioEntity(7025, "Günlük 26", "شرطة — محفظة ضائعة (B1)", "İyi günler, cüzdanımı kaybettim. Şikayetçi olmak istiyorum.\nNerede, ne zaman?\nBugün öğlen tramvayda.\nKimlik bilgileri… İfade alalım.", "أسلوب: Siz + جمل كاملة.", 0, "عام", "TR"),
        DailyScenarioEntity(7026, "Günlük 27", "صيانة إنترنت (A2)", "İnternet yok, iki gündür.\nArıza kaydı açıyorum. Bugün akşam bakacağız.\nSaat aralığı?\nBeş-yedi. Evde olun lütfen.", "حوار للاستماع والقراءة. راجع المكتبة المرجعية للشرح الكامل.", 0, "عام", "TR"),
        DailyScenarioEntity(7027, "Günlük 28", "جامعة / معهد (A2)", "Kayıt nerede yapılır?\nGirişte öğrenci işleri.\nŞu evraklar lazım mı?\nKimlik, fotoğraf, diploma fotokopisi.", "حوار للاستماع والقراءة. راجع المكتبة المرجعية للشرح الكامل.", 0, "عام", "TR"),
        DailyScenarioEntity(7028, "Pazar 29", "سوق خضار (A1–A2)", "Domates kaç lira?\nKilosu elli.\nBir kilo ver. Biraz daha olgun olsun.\nBuyur, tartıyorum. Başka?\nYok, sağ ol.", "ver هنا أمر يومي لطيف = أعطني. مع غريب أكبر: Verir misiniz?", 0, "سوق", "TR"),
        DailyScenarioEntity(7029, "Günlük 30", "رفض مهذب لدعوة (B1)", "Yarın sinemaya gelecek misin?\nÇok isterdim ama iş var. Bir dahaki sefere?\nTamam, kaçırma.", "لا تقل دائمًا: İstemiyorum فهي قاطعة.", 0, "عام", "TR"),
        DailyScenarioEntity(7030, "Günlük 31", "«Bakarız» ليست وعدًا (B1) — ثقافة", "Bu fiyatı düşürelim mi?\nBakarız, inşallah.", "معنى اجتماعي: ربما / دعنا نؤجل / غالبًا لا. لا تبنِ خطتك عليها.", 0, "عام", "TR"),
        DailyScenarioEntity(7031, "Sağlık 32", "طبيب أسنان موعد (A2)", "En yakın ne zaman randevu var?\nPerşembe saat üç.\nOlur, yazalım.", "حوار للاستماع والقراءة. راجع المكتبة المرجعية للشرح الكامل.", 0, "صحة", "TR"),
        DailyScenarioEntity(7032, "Günlük 33", "صيدلي يسأل حساسية (B1)", "İlacı daha önce kullandınız mı? Alerjiniz var mı?\nPenisiline alerjim var.\nO zaman bunu vermiyorum, alternatif vereyim.", "حوار للاستماع والقراءة. راجع المكتبة المرجعية للشرح الكامل.", 0, "عام", "TR"),
        DailyScenarioEntity(7033, "Pazar 34", "محل — لا يوجد مقاس (A2)", "Bunun otuz sekizi var mı?\nMaalesef tükendi. Üst beden deneyelim mi?\nOlur, bir bakalım.", "حوار للاستماع والقراءة. راجع المكتبة المرجعية للشرح الكامل.", 0, "سوق", "TR"),
        DailyScenarioEntity(7034, "Günlük 35", "توصيل طلب (A2)", "Siparişiniz var, imza lütfen.\nKutuyu açabilir miyim?\nTabii.\nTamam, sorun yok. İyi günler.\nKolay gelsin.", "حوار للاستماع والقراءة. راجع المكتبة المرجعية للشرح الكامل.", 0, "عام", "TR"),
        DailyScenarioEntity(7035, "Günlük 36", "إرجاع سلعة (B1)", "Bunu iade etmek istiyorum. Etiketi duruyor, giymedim.\nNeden?\nBeden olmadı.\nNakit mi iade, yoksa değişim mi?\nNakit lütfen.", "حوار للاستماع والقراءة. راجع المكتبة المرجعية للشرح الكامل.", 0, "عام", "TR"),
        DailyScenarioEntity(7036, "İş 37", "مقابلة عمل قصيرة (B2)", "Kendinizden bahseder misiniz?\nÜç yıldır satışta çalışıyorum. Türkçem orta, öğrenmeye devam ediyorum. Müşteriyle konuşmayı seviyorum.\nNeden biz?\nLokasyonunuz ve ekibiniz iyi görünüyor. Dürüst çalışırım.", "أسلوب: Siz، بلا عامية.", 0, "عمل", "TR"),
        DailyScenarioEntity(7037, "Günlük 38", "اجتماع قصير (B2)", "Gündem: teslimat gecikmesi.\nTedarikçi stok yetiştirememiş.\nMüşteriye ne diyoruz?\nÖzür dileyip yeni tarih veriyoruz: cuma.", "قاعدة: yetiştirememiş = قدرة + نفي + -miş (استنتاج/نقل).", 0, "عام", "TR"),
        DailyScenarioEntity(7038, "Pazar 39", "مزاح بائع مع زبون معتاد (B1)", "Yine mi geldin, kaçacak yerin kalmadı mı?\nSen çağırıyorsun durmadan.\nAl bari şunu, evde oturma.\nCimri deme, bak alıyorum işte.", "فقط إن كانت العلاقة مضحكة مسبقًا. وإلا وقاحة.", 0, "سوق", "TR"),
        DailyScenarioEntity(7039, "Tanışma 40", "مطر وصديق (A2)", "Hava berbat.\nŞemsiyen var mı?\nYok.\nGel, beraber gidelim.", "حوار للاستماع والقراءة. راجع المكتبة المرجعية للشرح الكامل.", 0, "تعارف", "TR"),
        DailyScenarioEntity(7040, "Günlük 41", "مشاعر — تعب (A2)", "N’oldu?\nÇok yorgunum, başım ağrıyor.\nGit yat, yarın konuşuruz.", "حوار للاستماع والقراءة. راجع المكتبة المرجعية للشرح الكامل.", 0, "عام", "TR"),
        DailyScenarioEntity(7041, "İş 42", "فرح — خبر عمل (B1)", "İşe aldılar!\nGözün aydın! Helal olsun.\nİlk çay benden.", "حوار للاستماع والقراءة. راجع المكتبة المرجعية للشرح الكامل.", 0, "عمل", "TR"),
        DailyScenarioEntity(7042, "Günlük 43", "تعزية قصيرة (B1) — رسمي–يومي", "Başın sağ olsun. Mekanı cennet olsun.\nTeşekkür ederim.\nAllah sabır versin. Bir ihtiyacın olursa ara.", "حوار للاستماع والقراءة. راجع المكتبة المرجعية للشرح الكامل.", 0, "عام", "TR"),
        DailyScenarioEntity(7043, "Seyahat 44", "طوارئ شارع (A1)", "İmdat! Yardım edin!\nNe oldu?\nAdam düştü, doktor lazım!\nHemen 112’yi arıyorum.", "حوار للاستماع والقراءة. راجع المكتبة المرجعية للشرح الكامل.", 0, "سفر", "TR"),
        DailyScenarioEntity(7044, "Günlük 45", "صراف آلي عطل (A2)", "Kartı yuttu. Ne yapacağım?\nBankayı ara, şube sabah açılıyor. Tutanağı biz tutalım.", "حوار للاستماع والقراءة. راجع المكتبة المرجعية للشرح الكامل.", 0, "عام", "TR"),
        DailyScenarioEntity(7045, "Günlük 46", "حلاق (A2)", "Nasıl keselim?\nKenarlar kısa, üst biraz uzun. Sakal düzelt.\nYıkayalım mı?\nEvet.", "حوار للاستماع والقراءة. راجع المكتبة المرجعية للشرح الكامل.", 0, "عام", "TR"),
        DailyScenarioEntity(7046, "Günlük 47", "مسجد / سؤال وقت (A1)", "Ezan kaçta?\nBirazdan. Abidesthane solda.", "حوار للاستماع والقراءة. راجع المكتبة المرجعية للشرح الكامل.", 0, "عام", "TR"),
        DailyScenarioEntity(7047, "İletişim 48", "شراء شريحة هاتف (A2)", "Turist hattı istiyorum. Pasaportum var.\nKaç GB?\nYirmi yeter. Kaç lira?\nBin iki yüz, bir ay.", "حوار للاستماع والقراءة. راجع المكتبة المرجعية للشرح الكامل.", 0, "اتصال", "TR"),
        DailyScenarioEntity(7048, "Günlük 49", "نهاية علاقة مهنية ليوم (محايد)", "Ben çıkıyorum, iyi akşamlar.\nİyi akşamlar, yarın görüşürüz.", "حوار للاستماع والقراءة. راجع المكتبة المرجعية للشرح الكامل.", 0, "عام", "TR"),
    )
}
